<script setup lang="ts">
// 首页与分析模块：六膳门工厂总览。迁自 liushanmen-v1/src/OperationalPages.vue 的首页部分。
import {computed,onMounted,ref,watch} from 'vue'
import UModal from '@nuxt/ui/components/Modal.vue'
import type {Source,Row,MenuEntry} from '../frame/types'
import {fmtQty} from '../frame/ai-protocol'
import FinanceLsm from './FinanceLsm.vue'
import RoleTodos from './RoleTodos.vue'
interface Inventory{factoryId:string;checkedAt:string;materialAt:string;revision:string;stock:Row[];orders:(Row&{lines:Row[]})[];warehouses:Row[]}
const props=defineProps<{source:Source;entry:MenuEntry}>(),emit=defineEmits<{open:[e:MenuEntry];inspect:[kind:string,row:Row]}>()
const inventory=ref<Inventory>(),busy=ref(false),error=ref(''),query=ref(''),filter=ref(''),page=ref(1),size=ref(20),selected=ref<Row>(),dialog=ref(false),message=ref('')
const fieldLabels:Record<string,string>={id:'来源ID',orderNo:'来源单号',orderType:'来源单据类型',bizTypeDisplay:'业务类型',bizAt:'业务时间',orderStatus:'来源状态编码',orderStatusDisplay:'来源状态',approvedAt:'审批时间',createdAt:'创建时间',updatedAt:'更新时间',productId:'产品来源ID',productName:'产品',productCode:'产品编码',warehouseId:'仓库来源ID',warehouseName:'仓库',warehouseCode:'仓库编码',qtyInWarehouse:'在库数量',unitName:'单位',code:'仓库编码',name:'仓库',status:'来源状态编码'};
const fmt=(x:unknown)=>x===null||x===undefined||x===''?'未记录':typeof x==='number'?x.toLocaleString('zh-CN',{maximumFractionDigits:4}):String(x)
const date=(x:unknown)=>x?String(x).includes('T')?new Date(String(x)).toLocaleString('zh-CN',{hour12:false}):String(x):'未记录'
async function read(){busy.value=true;error.value='';try{const r=await fetch('/api/inventory-source'),b=await r.json();if(!r.ok||!b.success||b.data.factoryId!=='LIUSHANMEN')throw Error(b.message||'库存来源读取失败');inventory.value=b.data}catch(e){error.value=e instanceof Error?e.message:'读取失败'}finally{busy.value=false}}
const home=computed(()=>props.entry.path==='/dashboard'),stockView=computed(()=>props.entry.path==='/warehouse/inventory-query'),warehouseView=computed(()=>props.entry.path==='/warehouse/storage-locations')
const resources=(k:string)=>props.source.resources[k]||[]
const counts=computed(()=>[ {label:'生产工单',value:resources('project').length,path:'/production/plans',page:'orders'},{label:'待审批报工',value:resources('output').filter(r=>String(r.approvalStatus)==='0').length,path:'/production/approval',page:'reports'},{label:'产品档案',value:resources('product').length,path:'/system/products',page:'products'},{label:'可比较成本工单',value:props.source.costs.filter(c=>c.unitCostAvailable).length,path:'/cost',page:'cost'}])
const states=computed(()=>[{id:'0',label:'新建',color:'#9aaabd'},{id:'10',label:'执行中',color:'#1b65a8'},{id:'20',label:'已结束',color:'#4a9c7b'},{id:'30',label:'已取消',color:'#b0b6c1'}].map(s=>({...s,count:resources('project').filter(r=>String(r.status)===s.id).length})))
const otherStates=computed(()=>resources('project').filter(r=>!['0','10','20','30'].includes(String(r.status))).length)
const issues=computed(()=>props.source.costs.filter(c=>c.issues.length).slice(0,6))
const recent=computed(()=>[...resources('project')].sort((a,b)=>String(b.updateTime||b.createTime||'').localeCompare(String(a.updateTime||a.createTime||''))).slice(0,8))
function open(path:string,title:string,page?:string){emit('open',{path,title,group:'六膳门业务',...(page?{page:page as MenuEntry['page']}:{})})}
const base=computed<Row[]>(()=>{if(stockView.value)return inventory.value?.stock||[];if(warehouseView.value)return inventory.value?.warehouses||[];const orders=inventory.value?.orders||[];return orders.filter(o=>props.entry.path==='/production/material-flow'?['生产领料出库','生产退料入库'].includes(String(o.bizTypeDisplay)):props.entry.path==='/warehouse/materials'?String(o.bizTypeDisplay).endsWith('入库'):props.entry.path==='/warehouse/shipments'?String(o.bizTypeDisplay).endsWith('出库'):false)})
const cols=computed(()=>stockView.value?[['productCode','产品编码'],['productName','产品'],['warehouseName','仓库'],['qtyInWarehouse','在库数量'],['unitName','单位']]:warehouseView.value?[['code','仓库编码'],['name','仓库'],['status','来源状态']]:[['orderNo','来源单号'],['bizTypeDisplay','业务类型'],['bizAt','业务时间'],['orderStatusDisplay','来源状态'],['lines','明细行数']])
const choices=computed(()=>[...new Set(base.value.map(r=>String(stockView.value?r.warehouseName||'未记录':r.bizTypeDisplay||r.status||'未记录')))])
const filtered=computed(()=>base.value.filter(r=>(!query.value||cols.value.some(([k])=>String(r[k]??'').toLowerCase().includes(query.value.toLowerCase())))&&(!filter.value||String(stockView.value?r.warehouseName||'未记录':r.bizTypeDisplay||r.status||'未记录')===filter.value)))
const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value)),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/size.value)))
function persist(){try{localStorage.setItem('liushanmen-operations:'+props.entry.path,JSON.stringify({query:query.value,filter:filter.value,page:page.value,size:size.value}))}catch{message.value='筛选偏好未保存，来源记录不受影响。'}}
function restore(){query.value='';filter.value='';page.value=1;size.value=20;try{const r=JSON.parse(localStorage.getItem('liushanmen-operations:'+props.entry.path)||'null');if(r){query.value=typeof r.query==='string'?r.query:'';filter.value=typeof r.filter==='string'?r.filter:'';size.value=[20,50,100].includes(r.size)?r.size:20;page.value=Number.isInteger(r.page)&&r.page>0?r.page:1}}catch{message.value='已使用默认筛选。'}}
function search(){page.value=1;persist()}
function reset(){query.value='';filter.value='';search()}
function inspect(row:Row){selected.value=row;dialog.value=true}
function csv(){const cells=(v:unknown)=>{let text=fmt(v);if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};const content=[cols.value.map(([,n])=>cells(n)).join(','),...filtered.value.map(r=>cols.value.map(([k])=>cells(k==='lines'?Array.isArray(r.lines)?r.lines.length:0:r[k])).join(','))].join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=props.entry.title+'-六膳门来源.csv';a.click();URL.revokeObjectURL(url)}
onMounted(async()=>{restore();await read()});watch(()=>props.entry.path,()=>{dialog.value=false;restore()})
</script>
<template><div class="operations-page"><div class="page-heading"><div><p>六膳门 · {{home?'工厂运营':'来源业务记录'}}</p><h1>{{home?'工厂总览':entry.title}}</h1></div><div class="actions"><button class="operation-button" @click="read" :disabled="busy">{{busy?'正在读取…':'重新读取'}}</button><button v-if="!home" class="operation-button" @click="csv">导出筛选</button></div></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p>
<template v-if="home"><p class="operation-source">生产来源 · 采集核验 {{date(source.checkedAt)}} · 库存／单据快照 {{date(inventory?.materialAt)}} · 来源时点分别保留</p><div class="home-kpis"><button v-for="k in counts" :key="k.label" @click="open(k.path,k.label,k.page)"><span>{{k.label}}</span><strong>{{k.value}}</strong><small>查看记录 →</small></button></div>
<RoleTodos :source="source" :orders="inventory?.orders" :inventory-at="inventory?.materialAt"/>
<FinanceLsm compact @more="open('/smart-bi/analysis-hub','经营分析')"/>
<div class="home-grid"><section class="card"><div class="section-head"><h2>生产执行</h2><button class="operation-link" @click="open('/production/plans','生产工单','orders')">全部工单 →</button></div><div class="home-status"><div class="status-track"><i v-for="s in states" :key="s.id" :style="{width:(s.count/Math.max(1,resources('project').length)*100)+'%',background:s.color}" :title="s.label+' '+s.count"/></div><div class="status-labels"><span v-for="s in states" :key="s.id"><i :style="{background:s.color}"/>{{s.label}} <b>{{s.count}}</b></span><span v-if="otherStates">其他状态 {{otherStates}}</span></div><p>按工单状态计数；取消单单列，不计作待执行需求。</p></div><table><thead><tr><th>工单 / 产品</th><th>计划量</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="r in recent" :key="String(r.id)"><td>{{r.projectCode}}<small>{{r.productName}}</small></td><td class="num">{{fmtQty(r.planAmount,String(r.projectUnit||''))}}</td><td>{{states.find(s=>s.id===String(r.status))?.label||'其他状态'}}</td><td><button class="operation-link" @click="emit('inspect','project',r)">详情</button></td></tr></tbody></table></section>
<div><section class="card"><div class="section-head"><h2>常用业务</h2></div><div class="home-shortcuts"><button @click="open('/production/process-hub','工序与工艺','processes')"><b>工艺配置</b><small>树 · 画布 · 配方 · 版本</small></button><button @click="open('/production/material-flow','领料')"><b>生产领退料</b><small>实际出库与退料单据</small></button><button @click="open('/warehouse/inventory-query','库存查询')"><b>库存查询</b><small>{{inventory?inventory.stock.length+' 条来源记录':'正在读取'}}</small></button><button @click="open('/cost','成本分析','cost')"><b>成本核对</b><small>实际材料 · 任务人工</small></button></div></section><section class="card"><div class="section-head"><h2>需要核对</h2><small>未满足核算条件</small></div><button v-for="c in issues" :key="String(c.projectId)" class="home-issue" @click="emit('inspect','project',resources('project').find(p=>String(p.id)===String(c.projectId))!)"><strong>{{c.projectCode}}</strong><span>{{c.issues.join('；')}}</span></button><p v-if="!issues.length" class="empty">当前未发现此类核对项。</p></section></div></div></template>
<UModal v-model:open="dialog" :title="String(selected?.orderNo||selected?.productName||selected?.name||'来源详情')"><template #body><div class="operation-detail"><p>六膳门 · 来源只读 · 不回写黑湖</p><dl><template v-for="(v,k) in selected" :key="k"><template v-if="k!=='lines'"><dt>{{fieldLabels[String(k)]||k}}</dt><dd>{{/id$/i.test(String(k))?v:fmt(v)}}</dd></template></template></dl><table v-if="Array.isArray(selected?.lines)"><thead><tr><th>产品 / 编码</th><th>数量 / 单位</th><th>源成本金额</th></tr></thead><tbody><tr v-for="l in selected.lines" :key="String(l.id)"><td>{{l.productName}}<small>{{l.productCode}}</small></td><td>{{fmt(l.qty)}} {{l.unitName}}</td><td>{{fmt(l.realCostAmount)}}</td></tr></tbody></table><p>单据数量与库存时点不同，不直接相减推算可用量。源成本金额币种待确认。</p></div></template></UModal></div></template>
<style scoped>
.operation-button{background:white;border:1px solid #d9e2eb;border-radius:6px;padding:7px 12px;font-size:12px}.operation-link{background:none;border:0;color:#1b65a8;font-size:12px;cursor:pointer}.operation-source{font-size:11px;color:#7b8c9f;margin:0 0 18px}.operation-boundary{padding:10px 14px;font-size:12px;color:#80652f;background:#fff8e9;border-radius:6px;margin-bottom:16px}.home-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.home-kpis button{background:white;border:1px solid #e0e6ee;border-radius:9px;padding:18px;text-align:left}.home-kpis span{font-size:12px;color:#6a7e92}.home-kpis strong{display:block;font-size:30px;font-weight:600;margin:8px 0;color:#263e56}.home-kpis small{font-size:11px;color:#1b65a8}.home-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,1fr);gap:18px}.home-status{padding:18px}.status-track{height:10px;border-radius:4px;overflow:hidden;background:#edf1f5;display:flex}.status-labels{display:flex;gap:18px;font-size:12px;margin-top:16px;flex-wrap:wrap}.status-labels i{display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:5px}.status-labels b{margin-left:6px}.home-status p{font-size:11px;color:#7c8da0;margin-top:10px}.home-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:14px}.home-shortcuts button{border:1px solid #e0e7ef;background:#fafcfe;border-radius:7px;padding:14px 10px;text-align:left}.home-shortcuts b{display:block;font-size:13px;font-weight:500}.home-shortcuts small{display:block;font-size:10px;margin-top:5px}.home-issue{display:block;width:100%;text-align:left;padding:11px 16px;border:0;border-bottom:1px solid #edf1f5;background:white}.home-issue strong{display:block;font-size:12px;font-weight:500}.home-issue span{display:block;font-size:11px;color:#8c7146;margin-top:4px}.operation-detail{font-size:12px}.operation-detail dl{display:grid;grid-template-columns:130px 1fr;gap:10px;margin:18px 0}.operation-detail dd{margin:0;overflow-wrap:anywhere}.operation-detail p{font-size:11px;color:#78889c}.operation-detail td{white-space:normal}@media(max-width:1100px){.home-grid{grid-template-columns:1fr}.home-kpis{gap:8px}}
</style>
